'use strict';

const os = require('os');
const yandexLogger = require('../../src');
const deployStream = require('../../streams/deploy');

describe('YandexLogger. Streams. Deploy', () => {
    let stream;
    let jestFakeTimers;

    beforeEach(() => {
        // Initialize a mock function to replace `write`.
        stream = { write: jest.fn() };

        // Use fake timers and set the system time
        jestFakeTimers = jest.useFakeTimers('modern');
        jest.setSystemTime(1000);
    });

    afterEach(() => {
        jestFakeTimers.clearAllTimers();
    });

    it('должен логировать записи в формате qloud в переданный стрим', () => {
        let logger = createLogger({ stream });

        let err = {
            name: 'Error name',
            message: 'Error message',
            stack: 'Error stack',
        };
        logger.info({ err, customField: 'foo' }, 'message');

        // Replacing Sinon's calledWithExactly with Jest's toHaveBeenCalledWith
        expect(stream.write).toHaveBeenCalledWith(JSON.stringify({
            msg: 'message',
            stackTrace: 'Error stack',
            level: 'INFO',
            levelStr: 'INFO',
            loggerName: 'yandex-logger',
            '@fields': {
                pid: process.pid,
                date: '1970-01-01T00:00:01.000Z',
                hostname: os.hostname(),
                level: 30,
                levelName: 'INFO',
                err: {
                    name: 'Error name',
                    message: 'Error message',
                    stack: 'Error stack',
                },
                customField: 'foo',
                msgFormat: 'message',
                msgArgs: [],
                msg: 'message',
                name: 'yandex-logger',
            },
        }) + '\n');

        // Replacing Sinon's calledOnce with Jest's toHaveBeenCalledTimes
        expect(stream.write).toHaveBeenCalledTimes(1);
    });

    it('должен логировать циклические записи', () => {
        let logger = createLogger({ stream });

        let circularObj = {};
        circularObj.circularRef = circularObj;
        circularObj.list = [circularObj, circularObj];

        logger.info({ circularObj }, 'message');

        expect(stream.write).toHaveBeenCalledWith(JSON.stringify({
            msg: 'message',
            level: 'INFO',
            levelStr: 'INFO',
            loggerName: 'yandex-logger',
            '@fields': {
                pid: process.pid,
                date: '1970-01-01T00:00:01.000Z',
                hostname: os.hostname(),
                level: 30,
                levelName: 'INFO',
                circularObj: {
                    circularRef: '[Circular ~.@fields.circularObj]',
                    list: [
                        '[Circular ~.@fields.circularObj]',
                        '[Circular ~.@fields.circularObj]',
                    ],
                },
                msgFormat: 'message',
                msgArgs: [],
                msg: 'message',
                name: 'yandex-logger',
            },
        }) + '\n');
        expect(stream.write).toHaveBeenCalledTimes(1);
    });

    it('должен убирать поля из excludeFields', () => {
        let logger = createLogger({ stream, excludeFields: ['field1', 'msg', 'msgArgs', 'msgFormat'] });

        logger.info({ field1: 'foo', field2: 'bar' }, 'message');

        expect(stream.write).toHaveBeenCalledWith(JSON.stringify({
            msg: 'message',
            level: 'INFO',
            levelStr: 'INFO',
            loggerName: 'yandex-logger',
            '@fields': {
                pid: process.pid,
                date: '1970-01-01T00:00:01.000Z',
                hostname: os.hostname(),
                level: 30,
                levelName: 'INFO',
                field2: 'bar',
                name: 'yandex-logger',
            },
        }) + '\n');
        expect(stream.write).toHaveBeenCalledTimes(1);
    });
});

function createLogger(config) {
    return yandexLogger({
        streams: [
            {
                stream: deployStream(config),
            },
        ],
    });
}
